<?php
namespace App\Http\Controllers;
use App\Models\{ActivityLog,Company,DataRecoveryCase,DataRecoveryQuote};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class DataRecoveryQuoteController extends Controller {
 public function create(DataRecoveryCase $dataRecovery){$this->authorizeCase($dataRecovery);abort_if($dataRecovery->quotes()->where('quote_type','!=','closure')->exists(),403,'Este caso ya tiene un presupuesto.');$dataRecovery->load(['company','client','homeServicePreorder']);$items=[['type'=>'recuperacion','description'=>'Servicio de recuperación de datos','quantity'=>1,'unit_price'=>0]];if($p=$dataRecovery->homeServicePreorder){if((float)$p->pickup_amount>0)$items[]=['type'=>'servicio','description'=>'Retiro a domicilio','quantity'=>1,'unit_price'=>round((float)$p->pickup_amount/1.19)];if((float)$p->delivery_amount>0)$items[]=['type'=>'servicio','description'=>'Entrega a domicilio','quantity'=>1,'unit_price'=>round((float)$p->delivery_amount/1.19)];}return view('data-recovery-quotes.create',['case'=>$dataRecovery,'items'=>$items]);}
 public function store(Request $r,DataRecoveryCase $dataRecovery){$this->authorizeCase($dataRecovery);abort_if($dataRecovery->quotes()->where('quote_type','!=','closure')->exists(),403,'Este caso ya tiene un presupuesto.');$data=$this->validated($r);$quote=DB::transaction(function()use($data,$dataRecovery,$r){$totals=$this->totals($data['items'],$data['discount_amount']??0);Company::whereKey($dataRecovery->company_id)->lockForUpdate()->firstOrFail();$q=DataRecoveryQuote::create(['company_id'=>$dataRecovery->company_id,'data_recovery_case_id'=>$dataRecovery->id,'quote_number'=>$this->nextNumber($dataRecovery->company_id),'status'=>'emitido','quote_type'=>'recovery','diagnosis_summary'=>$data['diagnosis_summary'],'discount_amount'=>$totals['discount'],'net_amount'=>$totals['net'],'tax_amount'=>$totals['tax'],'total_amount'=>$totals['total'],'valid_until'=>$data['valid_until']??null,'internal_notes'=>$data['internal_notes']??null]);$this->syncItems($q,$data['items']);$dataRecovery->update(['diagnosis'=>$data['diagnosis_summary']]);$this->status($dataRecovery,'presupuesto_enviado','Presupuesto emitido: '.$q->quote_number,$r->user()->id);return $q;});ActivityLog::record($r,'data_recovery_quote_created','Presupuesto creado: '.$quote->quote_number,$quote,$quote->company_id);return redirect()->route('data-recovery-quotes.show',$quote)->with('success','Presupuesto creado correctamente.');}
 public function show(DataRecoveryQuote $dataRecoveryQuote){$this->authorizeCase($dataRecoveryQuote->dataRecoveryCase);return view('data-recovery-quotes.show',['quote'=>$dataRecoveryQuote->load(['company','items','dataRecoveryCase.client'])]);}
 public function print(DataRecoveryQuote $dataRecoveryQuote){$this->authorizeCase($dataRecoveryQuote->dataRecoveryCase);return view('data-recovery-quotes.print',['quote'=>$dataRecoveryQuote->load(['company','items','dataRecoveryCase.client'])]);}
 public function approve(Request $r,DataRecoveryQuote $dataRecoveryQuote){return $this->respond($r,$dataRecoveryQuote,'aprobado');} public function reject(Request $r,DataRecoveryQuote $dataRecoveryQuote){return $this->respond($r,$dataRecoveryQuote,'rechazado');}
 public function destroy(Request $r,DataRecoveryQuote $dataRecoveryQuote){$case=$dataRecoveryQuote->dataRecoveryCase;$this->authorizeCase($case);$number=$dataRecoveryQuote->quote_number;DB::transaction(function()use($case,$dataRecoveryQuote,$r,$number){DataRecoveryQuote::where('parent_quote_id',$dataRecoveryQuote->id)->delete();$dataRecoveryQuote->delete();if(!$case->quotes()->where('quote_type','!=','closure')->exists())$this->status($case,'diagnosticado','Presupuesto eliminado: '.$number,$r->user()->id);});ActivityLog::record($r,'data_recovery_quote_deleted','Presupuesto eliminado: '.$number,null,$case->company_id);return redirect()->route('data-recovery.show',$case)->with('success','Presupuesto eliminado correctamente.');}
 private function respond(Request $r,DataRecoveryQuote $q,string $status){$case=$q->dataRecoveryCase;$this->authorizeCase($case);$data=$r->validate(['customer_response_notes'=>['nullable','string'],'customer_pickup'=>['nullable','boolean']]);DB::transaction(function()use($r,$q,$case,$status,$data){$q->update(['status'=>$status,'approved_at'=>$status==='aprobado'?now():null,'rejected_at'=>$status==='rechazado'?now():null,'customer_response_notes'=>$data['customer_response_notes']??null]);if($q->quote_type!=='closure')$this->status($case,$status==='aprobado'?'aprobado':'rechazado','Presupuesto '.$status.': '.$q->quote_number,$r->user()->id);if($status==='rechazado'&&$q->quote_type!=='closure')$this->createClosureQuote($q,!($data['customer_pickup']??false));});ActivityLog::record($r,'data_recovery_quote_'.$status,'Presupuesto '.$status.': '.$q->quote_number,$q,$q->company_id);return redirect()->route('data-recovery-quotes.show',$q)->with('success','Presupuesto '.$status.'.');}
 private function createClosureQuote(DataRecoveryQuote $source,bool $includeDelivery=true):void{if($source->quote_type==='closure'||DataRecoveryQuote::where('parent_quote_id',$source->id)->exists())return;$source->loadMissing(['dataRecoveryCase.company','dataRecoveryCase.homeServicePreorder']);$gross=(float)($source->dataRecoveryCase->company->diagnostic_fee_gross??20000);$items=[['type'=>'diagnostico','description'=>'Diagnóstico (cobro por presupuesto no aprobado)','quantity'=>1,'unit_price'=>round($gross/1.19)]];$p=$source->dataRecoveryCase->homeServicePreorder;if($p&&(float)$p->pickup_amount>0)$items[]=['type'=>'servicio','description'=>'Retiro a domicilio','quantity'=>1,'unit_price'=>round((float)$p->pickup_amount/1.19)];if($includeDelivery&&$p&&(float)$p->delivery_amount>0)$items[]=['type'=>'servicio','description'=>'Entrega a domicilio','quantity'=>1,'unit_price'=>round((float)$p->delivery_amount/1.19)];$totals=$this->totals($items,0);$q=DataRecoveryQuote::create(['company_id'=>$source->company_id,'data_recovery_case_id'=>$source->data_recovery_case_id,'quote_number'=>$this->nextNumber($source->company_id),'status'=>'emitido','quote_type'=>'closure','parent_quote_id'=>$source->id,'diagnosis_summary'=>'Liquidación por presupuesto de recuperación no aprobado.','discount_amount'=>0,'net_amount'=>$totals['net'],'tax_amount'=>$totals['tax'],'total_amount'=>$totals['total']]);$this->syncItems($q,$items);}
 private function syncItems(DataRecoveryQuote $q,array $items):void{foreach($items as $i)$q->items()->create($i+['total'=>(int)$i['quantity']*(float)$i['unit_price']]);}
 private function nextNumber(int $company):string{return 'PRES-RD-'.str_pad((string)(DataRecoveryQuote::where('company_id',$company)->count()+1),6,'0',STR_PAD_LEFT);}
 private function validated(Request $r):array{return $r->validate(['diagnosis_summary'=>['required','string'],'valid_until'=>['nullable','date'],'discount_amount'=>['nullable','numeric','min:0'],'internal_notes'=>['nullable','string'],'items'=>['required','array','min:1'],'items.*.type'=>['required','in:diagnostico,recuperacion,repuesto,servicio'],'items.*.description'=>['required','string','max:255'],'items.*.quantity'=>['required','integer','min:1'],'items.*.unit_price'=>['required','numeric','min:0']]);}
 private function totals(array $items,float|int $discount):array{$subtotal=collect($items)->sum(fn($i)=>(int)$i['quantity']*(float)$i['unit_price']);$net=max($subtotal-(float)$discount,0);$tax=round($net*.19);return ['discount'=>(float)$discount,'net'=>$net,'tax'=>$tax,'total'=>$net+$tax];}
 private function status(DataRecoveryCase $case,string $status,string $comment,int $user):void{$case->update(['status'=>$status]);$case->statusLogs()->create(['user_id'=>$user,'status'=>$status,'comment'=>$comment]);}
 private function authorizeCase(DataRecoveryCase $case):void{abort_if(request()->user()->role!=='super_admin'&&$case->company_id!==request()->user()->company_id,403);}
}
